//! Hot-text grouping (PAGEFAULTS-2): the library's startup, stdio, printf and setlocale functions
//! are scattered over the ~3 MB `.text` of a static program, and every first touch of a 64 KiB
//! window is a file-backed page fault (fault-around maps 64 KiB per fault): a `setlocale(LC_ALL,
//! "")` + `printf` program took 34 text faults. The functions that such programs execute are
//! listed in `crates/libc-so/hot-text.list` (generated by `tools/hottext/regen.sh`, which traces
//! probe programs with gdb), and their sections are renamed `.text.<f>` -> `.text.hot.<f>` in
//! the archive. The program's own static link then gathers them: GNU ld's (and gold's) default
//! script places `*(.text.hot .text.hot.*)` together ahead of the rest of `.text`. No symbol,
//! ABI or behaviour changes; with a linker that ignores the prefix the order is merely unchanged.
//! Each function keeps its own section, so `--gc-sections` still drops the unused ones.
//!
//! HOT-ORDER: the list is a layout order (first touch: startup, then stdio, strings, setlocale,
//! printf), and object order scattered the startup functions through a 300 KiB group (an empty
//! program touched one 64 KiB window more after the group grew). The sections are therefore named
//! `.text.sorted.h<index>.<f>`: GNU ld's default script (binutils >= 2.36) places
//! `*(SORT(.text.sorted.*))` right after `.text.hot.*`, sorted by name, i.e. by list position
//! across all objects. A linker without that rule merges them into `.text` (today's order).

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::Path;
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};

use crate::so::OWN_PREFIX;

/// HOTTEXT-REGEN-UNBLOCK: `cargo xtask so --hottext-regen` builds the products with the dead-key
/// check of [`group`] reported but not enforced. A stale start-up or fork key blocks the build, and
/// the build is what `tools/hottext/regen.sh` traces to repair the list, so without this mode a dead
/// key blocks its own repair. Only `regen.sh --build` passes it, and it then rebuilds without it, so
/// the rewritten list must pass the check; [`static_check`] fails when anything else names it.
pub const REGEN_FLAG: &str = "--hottext-regen";
static REGEN: AtomicBool = AtomicBool::new(false);

/// HOTLIST-REGEN-CHEAP: `cargo xtask so --hottext-regen --libc-only <dir>` builds only what the regen's
/// traces link (`libc.a`, `liella-crt1.o` and the `.profile` marker) into `<dir>`, never into
/// `target/liella`: no libc.so.6, libm, ld.so or layout check (79% of a regen was product builds).
pub const LIBC_ONLY_FLAG: &str = "--libc-only";

/// The arguments of `cargo xtask so`: [`REGEN_FLAG`] turns the regen mode on; it is refused under
/// CI (the `CI` variable set). [`LIBC_ONLY_FLAG`] `<dir>` (only with [`REGEN_FLAG`]) returns `<dir>`.
/// Any other argument is an error.
pub fn regen_mode(args: &[String]) -> Result<Option<std::path::PathBuf>, String> {
    let mut on = false;
    let mut libc_only = None;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        if a == REGEN_FLAG {
            on = true;
        } else if a == LIBC_ONLY_FLAG {
            let dir = it.next().filter(|d| !d.is_empty()).ok_or_else(|| format!("so: {LIBC_ONLY_FLAG} needs a directory"))?;
            libc_only = Some(std::path::PathBuf::from(dir));
        } else {
            return Err(format!("so: unknown argument {a:?} (the only ones are {REGEN_FLAG} [{LIBC_ONLY_FLAG} <dir>], for tools/hottext/regen.sh)"));
        }
    }
    if libc_only.is_some() && !on {
        return Err(format!("so: {LIBC_ONLY_FLAG} builds regen products only: it needs {REGEN_FLAG}"));
    }
    if on && std::env::var_os("CI").is_some_and(|v| !v.is_empty()) {
        return Err(format!("so: {REGEN_FLAG} is for tools/hottext/regen.sh only, never under CI"));
    }
    REGEN.store(on, Ordering::Relaxed);
    Ok(libc_only)
}

/// Whether this run builds in the regen mode ([`REGEN_FLAG`]).
pub fn regen_on() -> bool {
    REGEN.load(Ordering::Relaxed)
}

/// The archive exactly as [`group`] received it in a regen build (`target/product/<profile>/`), kept so
/// that [`recheck_cmd`] can rerun the grouping alone on the rewritten list.
pub const PRE_GROUP_ARCHIVE: &str = "hot-text.pre-group.a";

/// `cargo xtask hottext-recheck` (HOTLIST-REGEN-CHEAP): the check a regen ends with, without a second
/// full `cargo xtask so`. For each profile, [`group`] (the grouping, its cluster check and the
/// dead-key check of [`dead_key_verdict`]: warnings, failing only under [`PROMOTE_ENV`]) runs again on a copy of [`PRE_GROUP_ARCHIVE`] with the
/// rewritten `crates/libc-so/hot-text.list`. Fails when a profile has no such archive (run
/// `regen.sh . --both` first) or when the check fails.
pub fn recheck_cmd(root: &Path, args: &[String]) -> Result<(), String> {
    if !args.is_empty() {
        return Err("usage: cargo xtask hottext-recheck".into());
    }
    let ar = std::env::var("AR").unwrap_or_else(|_| "ar".into());
    let product = root.join("target/product");
    let list = crate::hotlists::path(root, "hot-text.list")?;
    let inputs = root.join(crate::hotlists::TRACKED);
    for p in [crate::so::Profile::Fast, crate::so::Profile::Release] {
        let dir = product.join(p.name());
        let saved = dir.join(PRE_GROUP_ARCHIVE);
        if !saved.is_file() {
            return Err(format!("hottext-recheck: {} missing (build the {} regen products first: tools/hottext/regen.sh . --both)", saved.display(), p.name()));
        }
        let copy = dir.join("hot-text.recheck.a");
        fs::copy(&saved, &copy).map_err(|e| format!("hottext-recheck: copy {}: {e}", saved.display()))?;
        let r = group(&ar, &copy, &list, &inputs, &dir.join("recheck-work"), Some(p.name()));
        let _ = fs::remove_file(&copy);
        let (hot, keys) = r.map_err(|e| format!("hottext-recheck: {}: {e}", p.name()))?;
        println!("hottext-recheck: {}: {hot} function sections grouped, {keys} keys, dead-key check done", p.name());
    }
    Ok(())
}

/// A function or section name -> its build-stable key (keep in step with tools/hottext/keys.py):
/// no `__liella_libc_` prefix, no ThinLTO `.llvm.<n>` suffix, no v0 crate disambiguators
/// (`Cs<base62>_` -> `C`), no legacy hash (`17h<16 hex>E` -> `E`).
/// HOTTEXT-FAULT-ENV: v0 back-references (`B<base62>_`) are byte offsets into the mangled name,
/// so they move when a crate disambiguator changes length (the disambiguators of the workspace
/// crates differ between checkouts); dropping only `Cs<hash>_` left keys that matched in one
/// role and not in another (34 generic functions fell out of the hot group). The v0 key is
/// therefore the name re-written with every back-reference expanded in place ([`canon_v0`]);
/// a name that does not parse keeps the plain disambiguator strip.
pub fn key(name: &str) -> String {
    let name = name.strip_prefix(OWN_PREFIX).unwrap_or(name);
    let mut s = strip_llvm(name);
    if s.starts_with("_R") {
        s = canon_v0(&s).unwrap_or_else(|| strip_crate_hashes(&s));
    }
    if s.starts_with("_ZN") {
        s = strip_legacy_hash(&s);
    }
    s
}

fn strip_llvm(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(i) = rest.find(".llvm.") {
        let after = &rest[i + 6..];
        let digits = after.bytes().take_while(u8::is_ascii_digit).count();
        if digits == 0 {
            out.push_str(&rest[..i + 6]);
        } else {
            out.push_str(&rest[..i]);
        }
        rest = &after[digits..];
    }
    out.push_str(rest);
    out
}

/// A v0 symbol (`_R...`, Rust symbol-mangling v0 grammar) re-written without crate-root
/// disambiguators and with every back-reference replaced by the text it refers to. Anything
/// after the instantiating crate (`.specialized.1`, ...) is kept. `None` if the name does not
/// parse (the caller falls back to [`strip_crate_hashes`]).
fn canon_v0(s: &str) -> Option<String> {
    let rest = s.strip_prefix("_R")?;
    let mut d = V0 { b: rest.as_bytes(), depth: 0 };
    let mut out = String::from("_R");
    let mut i = 0;
    if d.b.first()?.is_ascii_digit() {
        i = d.decimal(0)?.1;
        out.push_str(&rest[..i]);
    }
    i = d.path(i, &mut out)?;
    if i < d.b.len() && d.b[i] != b'.' {
        i = d.path(i, &mut out)?;
    }
    out.push_str(rest.get(i..)?);
    Some(out)
}

/// The v0 walker of [`canon_v0`]: each method parses one production at byte `i` (offset after
/// `_R`, the base of back-references), appends its canonical form to `out` and returns the end.
struct V0<'a> {
    b: &'a [u8],
    depth: u32,
}

impl V0<'_> {
    fn at(&self, i: usize) -> Option<u8> {
        self.b.get(i).copied()
    }

    /// `<decimal-number>` -> (value, end).
    fn decimal(&self, mut i: usize) -> Option<(usize, usize)> {
        let start = i;
        while self.at(i)?.is_ascii_digit() {
            i += 1;
            if i >= self.b.len() {
                break;
            }
        }
        let n = std::str::from_utf8(self.b.get(start..i)?).ok()?.parse().ok()?;
        (i > start).then_some((n, i))
    }

    /// `<base-62-number>` (`_` = 0, else digits + 1, then `_`) -> (value, end).
    fn base62(&self, mut i: usize) -> Option<(usize, usize)> {
        if self.at(i)? == b'_' {
            return Some((0, i + 1));
        }
        let mut v: usize = 0;
        loop {
            let c = self.at(i)?;
            i += 1;
            let digit = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'z' => c - b'a' + 10,
                b'A'..=b'Z' => c - b'A' + 36,
                b'_' => return Some((v.checked_add(1)?, i)),
                _ => return None,
            };
            v = v.checked_mul(62)?.checked_add(usize::from(digit))?;
        }
    }

    /// Copies `b[from..to]` to `out`.
    fn copy(&self, from: usize, to: usize, out: &mut String) -> Option<usize> {
        out.push_str(std::str::from_utf8(self.b.get(from..to)?).ok()?);
        Some(to)
    }

    /// `B<base-62-number>`: parses the production `f` at the target, returns the end of the reference.
    fn backref(&mut self, i: usize, out: &mut String, f: fn(&mut Self, usize, &mut String) -> Option<usize>) -> Option<usize> {
        let (target, end) = self.base62(i + 1)?;
        if target >= i || self.depth > 64 {
            return None;
        }
        self.depth += 1;
        f(self, target, out)?;
        self.depth -= 1;
        Some(end)
    }

    /// `<undisambiguated-identifier>`: `[u] <decimal> [_] <bytes>`, copied.
    fn ident(&self, i: usize, out: &mut String) -> Option<usize> {
        let j = if self.at(i)? == b'u' { i + 1 } else { i };
        let (n, mut k) = self.decimal(j)?;
        if self.at(k) == Some(b'_') {
            k += 1;
        }
        self.copy(i, k.checked_add(n)?, out)
    }

    /// `[s <base-62-number>] <undisambiguated-identifier>`; `keep` = copy the disambiguator.
    fn disambiguated(&self, mut i: usize, keep: bool, out: &mut String) -> Option<usize> {
        if self.at(i)? == b's' {
            let end = self.base62(i + 1)?.1;
            if keep {
                self.copy(i, end, out)?;
            }
            i = end;
        }
        self.ident(i, out)
    }

    /// `[s <base-62-number>] <path>` (impl-path; impl disambiguators are stable, kept).
    fn impl_path(&mut self, mut i: usize, out: &mut String) -> Option<usize> {
        if self.at(i)? == b's' {
            i = self.copy(i, self.base62(i + 1)?.1, out)?;
        }
        self.path(i, out)
    }

    fn path(&mut self, i: usize, out: &mut String) -> Option<usize> {
        let c = self.at(i)?;
        match c {
            b'C' => {
                out.push('C');
                self.disambiguated(i + 1, false, out)
            }
            b'M' => {
                out.push('M');
                let j = self.impl_path(i + 1, out)?;
                self.ty(j, out)
            }
            b'X' => {
                out.push('X');
                let j = self.impl_path(i + 1, out)?;
                let j = self.ty(j, out)?;
                self.path(j, out)
            }
            b'Y' => {
                out.push('Y');
                let j = self.ty(i + 1, out)?;
                self.path(j, out)
            }
            b'N' => {
                let ns = self.at(i + 1)?;
                if !ns.is_ascii_alphabetic() {
                    return None;
                }
                out.push('N');
                out.push(char::from(ns));
                let j = self.path(i + 2, out)?;
                self.disambiguated(j, true, out)
            }
            b'I' => {
                out.push('I');
                let mut j = self.path(i + 1, out)?;
                while self.at(j)? != b'E' {
                    j = self.generic_arg(j, out)?;
                }
                out.push('E');
                Some(j + 1)
            }
            b'B' => self.backref(i, out, Self::path),
            _ => None,
        }
    }

    fn generic_arg(&mut self, i: usize, out: &mut String) -> Option<usize> {
        match self.at(i)? {
            b'L' => self.copy(i, self.base62(i + 1)?.1, out),
            b'K' => {
                out.push('K');
                self.konst(i + 1, out)
            }
            _ => self.ty(i, out),
        }
    }

    /// `<const>`: placeholder, back-reference or `<basic type> [n] <hex digits> _`.
    fn konst(&mut self, i: usize, out: &mut String) -> Option<usize> {
        match self.at(i)? {
            b'p' => self.copy(i, i + 1, out),
            b'B' => self.backref(i, out, Self::konst),
            c if c.is_ascii_lowercase() => {
                let mut j = i + 1;
                if self.at(j)? == b'n' {
                    j += 1;
                }
                while self.at(j)?.is_ascii_hexdigit() {
                    j += 1;
                }
                if self.at(j)? != b'_' {
                    return None;
                }
                self.copy(i, j + 1, out)
            }
            _ => None,
        }
    }

    fn lifetime_opt(&self, i: usize, out: &mut String) -> Option<usize> {
        if self.at(i)? == b'L' { self.copy(i, self.base62(i + 1)?.1, out) } else { Some(i) }
    }

    fn binder_opt(&self, i: usize, out: &mut String) -> Option<usize> {
        if self.at(i)? == b'G' { self.copy(i, self.base62(i + 1)?.1, out) } else { Some(i) }
    }

    fn ty(&mut self, i: usize, out: &mut String) -> Option<usize> {
        let c = self.at(i)?;
        match c {
            b'a'..=b'f' | b'h' | b'i' | b'j' | b'l' | b'm' | b'n' | b'o' | b'p' | b's' | b't' | b'u' | b'v' | b'x' | b'y' | b'z' => {
                self.copy(i, i + 1, out)
            }
            b'A' => {
                out.push('A');
                let j = self.ty(i + 1, out)?;
                self.konst(j, out)
            }
            b'S' | b'P' | b'O' => {
                out.push(char::from(c));
                self.ty(i + 1, out)
            }
            b'R' | b'Q' => {
                out.push(char::from(c));
                let j = self.lifetime_opt(i + 1, out)?;
                self.ty(j, out)
            }
            b'T' => {
                out.push('T');
                let mut j = i + 1;
                while self.at(j)? != b'E' {
                    j = self.ty(j, out)?;
                }
                out.push('E');
                Some(j + 1)
            }
            b'F' => {
                out.push('F');
                let mut j = self.binder_opt(i + 1, out)?;
                if self.at(j)? == b'U' {
                    j = self.copy(j, j + 1, out)?;
                }
                if self.at(j)? == b'K' {
                    out.push('K');
                    j = if self.at(j + 1)? == b'C' { self.copy(j + 1, j + 2, out)? } else { self.ident(j + 1, out)? };
                }
                while self.at(j)? != b'E' {
                    j = self.ty(j, out)?;
                }
                out.push('E');
                self.ty(j + 1, out)
            }
            b'D' => {
                out.push('D');
                let mut j = self.binder_opt(i + 1, out)?;
                while self.at(j)? != b'E' {
                    j = self.path(j, out)?;
                    while self.at(j)? == b'p' {
                        out.push('p');
                        j = self.ident(j + 1, out)?;
                        j = self.ty(j, out)?;
                    }
                }
                out.push('E');
                self.lifetime_opt(j + 1, out)
            }
            b'B' => self.backref(i, out, Self::ty),
            _ => self.path(i, out),
        }
    }

    /// `[s <base-62-number>] <decimal> [_] <bytes>` (not punycode) -> (identifier, end).
    fn name(&self, mut i: usize) -> Option<(String, usize)> {
        if self.at(i)? == b's' {
            i = self.base62(i + 1)?.1;
        }
        let (n, mut k) = self.decimal(i)?;
        if self.at(k) == Some(b'_') {
            k += 1;
        }
        let end = k.checked_add(n)?;
        Some((std::str::from_utf8(self.b.get(k..end)?).ok()?.to_string(), end))
    }

    /// The parent of a function's name (see [`fn_site`]): `C` crate, `Nt` module, `M` inherent impl
    /// or `X` trait impl -> (crate, modules, the self type's name for an impl, end).
    fn owner(&mut self, i: usize) -> Option<(String, Vec<String>, Option<String>, usize)> {
        match self.at(i)? {
            b'C' => self.name(i + 1).map(|(k, e)| (k, Vec::new(), None, e)),
            b'N' if self.at(i + 1)? == b't' => {
                let (k, mut mods, None, j) = self.owner(i + 2)? else { return None };
                let (m, e) = self.name(j)?;
                mods.push(m);
                Some((k, mods, None, e))
            }
            c @ (b'M' | b'X') => {
                let j = if self.at(i + 1)? == b's' { self.base62(i + 2)?.1 } else { i + 1 };
                let (k, mods, None, j) = self.owner(j)? else { return None };
                let mut e = self.ty(j, &mut String::new())?;
                let named = if self.at(j)? == b'I' { j + 1 } else { j };
                if self.at(named)? != b'N' {
                    return None;
                }
                let parent_end = self.path(named + 2, &mut String::new())?;
                let ty = self.name(parent_end)?.0;
                if c == b'X' {
                    e = self.path(e, &mut String::new())?;
                }
                Some((k, mods, Some(ty), e))
            }
            _ => None,
        }
    }
}

fn strip_crate_hashes(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'C' && b.get(i + 1) == Some(&b's') {
            let run = b[i + 2..].iter().take_while(|c| c.is_ascii_alphanumeric()).count();
            if run > 0 && b.get(i + 2 + run) == Some(&b'_') {
                out.push('C');
                i += 3 + run;
                continue;
            }
        }
        out.push(b[i] as char);
        i += 1;
    }
    out
}

fn strip_legacy_hash(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < b.len() {
        if b[i..].starts_with(b"17h") && b.len() >= i + 20 && b[i + 3..i + 19].iter().all(u8::is_ascii_hexdigit) && b[i + 19] == b'E' {
            out.push('E');
            i += 20;
            continue;
        }
        out.push(b[i] as char);
        i += 1;
    }
    out
}

/// The tiers of `hot-text.list` (HOTTEXT-STARTUP-COMPLETE), in first-touch order: the probe that
/// touched a key first (tools/hottext/regen.sh). Keep in step with tools/hottext/merge.py.
const TIERS: [&str; 7] = ["startup", "fork", "stdio", "strings", "locale", "tool", "extra"];
/// The allow-list of keys that legitimately match no function section in one profile's archive,
/// next to `hot-text.list` (STARTUP-FAULTS-RESTORE): `<key>\t<profile>\t<reason>`.
pub const ABSENT_LIST: &str = "hot-text.absent";

/// One key of the list: its tier and the profiles whose trace hit it (empty: none recorded).
#[derive(Debug, PartialEq)]
pub(crate) struct Entry {
    pub(crate) key: String,
    pub(crate) tier: &'static str,
    profiles: Vec<String>,
}

/// The lines of `hot-text.list`: `<key>\t<tier>\t<profiles>` (profiles comma-separated, `-` for
/// none); `#` comments and blank lines skipped. A line with the key alone (the list before tiers)
/// has tier `extra` and no profile. Errors name the line.
pub(crate) fn parse_list(text: &str) -> Result<Vec<Entry>, String> {
    let mut out = Vec::new();
    for (n, l) in text.lines().enumerate() {
        if l.trim().is_empty() || l.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = l.split('\t').collect();
        let bad = || format!("hot-text.list line {}: {l:?}: want <key>\\t<tier>\\t<profiles>", n + 1);
        let entry = match parts[..] {
            [k] => Entry { key: k.trim().to_string(), tier: "extra", profiles: Vec::new() },
            [k, t, p] => {
                let tier = TIERS.iter().find(|x| **x == t).ok_or_else(bad)?;
                let profiles: Vec<String> = if p == "-" { Vec::new() } else { p.split(',').map(str::to_string).collect() };
                if profiles.iter().any(|p| p != "fast" && p != "release") {
                    return Err(bad());
                }
                Entry { key: k.to_string(), tier, profiles }
            }
            _ => return Err(bad()),
        };
        out.push(entry);
    }
    Ok(out)
}

/// The keys of `entries` -> their position (the first, if a key repeats).
fn positions(entries: &[Entry]) -> BTreeMap<String, usize> {
    let mut keys = BTreeMap::new();
    for (i, e) in entries.iter().enumerate() {
        keys.entry(e.key.clone()).or_insert(i);
    }
    keys
}

/// LAYOUT-FIRST-WINDOW (D-X, pending record): hand-kept keys, next to the list, that the link places
/// right after the start-up tier, in this file's order: `<key> TAB <reason>`, `#` comments. The
/// kernel maps a file's text in 64 KiB fault-around windows; the first fault of a static program
/// maps the 16 pages from the start of its text segment, and the start-up tier fills most of them.
/// A function every short program with stdio or a zone load runs, but the `true` probe does not
/// (so it is not start-up tier), sat behind keys no fault-bounded probe runs (`puts`), and a
/// 0x240-byte start-up growth moved it one page past that window (one more fault in four release
/// probes, #5026). Listed here, it follows the start-up tier whatever the generated order.
pub const FIRST_WINDOW_LIST: &str = "hot-text.first-window";

/// The keys of [`FIRST_WINDOW_LIST`] in file order. Every line needs a reason. Errors name the line.
fn parse_first_window(text: &str) -> Result<Vec<String>, String> {
    let mut out: Vec<String> = Vec::new();
    for (n, l) in text.lines().enumerate() {
        if l.trim().is_empty() || l.starts_with('#') {
            continue;
        }
        let Some((k, _)) = l.split_once('\t').filter(|(k, r)| !k.is_empty() && !r.trim().is_empty()) else {
            return Err(format!("{FIRST_WINDOW_LIST} line {}: {l:?}: want <key>\\t<reason>", n + 1));
        };
        if out.iter().any(|o| o == k) {
            return Err(format!("{FIRST_WINDOW_LIST} line {}: {k} is listed twice", n + 1));
        }
        out.push(k.to_string());
    }
    Ok(out)
}

/// The link position of each key (as [`positions`]) with the keys `first` moved, in their order,
/// right after the start-up tier (the list's leading `startup` entries). A key must be in the list,
/// outside the start-up tier (a line that a regen made redundant is stale) and outside every
/// cluster of `clusters` (list positions: a moved key would split its cluster's range).
fn link_positions(entries: &[Entry], first: &[String], clusters: &[Cluster]) -> Result<BTreeMap<String, usize>, String> {
    let list = positions(entries);
    let head = entries.iter().take_while(|e| e.tier == "startup").count();
    for k in first {
        let Some(&p) = list.get(k) else {
            return Err(format!("{FIRST_WINDOW_LIST}: {k} is not in hot-text.list (renamed or dropped by a regen? update the line)"));
        };
        if p < head {
            return Err(format!("{FIRST_WINDOW_LIST}: {k} is in the start-up tier now (position {p}); remove its line"));
        }
        if let Some(c) = clusters.iter().find(|c| (c.first..=c.last).contains(&p)) {
            return Err(format!("{FIRST_WINDOW_LIST}: {k} (position {p}) lies inside cluster {} ({}..={}); a cluster's keys stay together", c.name, c.first, c.last));
        }
    }
    let moved: BTreeSet<&str> = first.iter().map(String::as_str).collect();
    let order = entries[..head].iter().map(|e| e.key.as_str()).chain(first.iter().map(String::as_str)).chain(entries[head..].iter().map(|e| e.key.as_str()).filter(|k| !moved.contains(k)));
    let mut keys = BTreeMap::new();
    for (i, k) in order.enumerate() {
        keys.entry(k.to_string()).or_insert(i);
    }
    Ok(keys)
}

/// [`link_positions`] for `entries`, with the hand-written [`FIRST_WINDOW_LIST`] in `inputs`
/// (none: the list's own positions) and the clusters of `clusters_text` ([`CLUSTER_LIST`]).
/// `inputs` is the hand-written input directory (hotlists' TRACKED), never the directory of a
/// train-owned list copy.
fn first_window_positions(inputs: &Path, entries: &[Entry], clusters_text: Option<&str>) -> Result<BTreeMap<String, usize>, String> {
    let path = inputs.join(FIRST_WINDOW_LIST);
    let first = match fs::read_to_string(&path) {
        Ok(t) => parse_first_window(&t)?,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(e) => return Err(format!("{}: {e}", path.display())),
    };
    let clusters = match clusters_text {
        Some(t) => parse_clusters(t, &positions(entries))?,
        None => Vec::new(),
    };
    link_positions(entries, &first, &clusters)
}

/// The lines of [`ABSENT_LIST`]: (key, profile) pairs. Every line needs a reason; `#` comments
/// and blank lines are skipped. Errors name the line.
fn parse_absent(text: &str) -> Result<BTreeSet<(String, String)>, String> {
    let mut out = BTreeSet::new();
    for (n, l) in text.lines().enumerate() {
        if l.trim().is_empty() || l.starts_with('#') {
            continue;
        }
        match l.split('\t').collect::<Vec<_>>()[..] {
            [k, p @ ("fast" | "release"), why] if !k.is_empty() && !why.trim().is_empty() => {
                out.insert((k.to_string(), p.to_string()));
            }
            _ => return Err(format!("{ABSENT_LIST} line {}: {l:?}: want <key>\\t<fast|release>\\t<reason>", n + 1)),
        }
    }
    Ok(out)
}

/// The dead-key contract (STARTUP-FAULTS-RESTORE; HOTTEXT-STARTUP-COMPLETE guarded the start-up
/// and fork tiers only). In an archive built with `profile`, every key must match a function
/// section (`matched`) unless its trace names only the other profile (inlined or absent there)
/// or [`ABSENT_LIST`] (`absent`) allows it for `profile`: a key that matches nothing places
/// nothing, so a function renamed (made generic, inlined) silently leaves the group
/// (DL-BOOT-RELOC-7: `runtime::start` became `start::<false>`, two more start-up faults).
/// Returns the unmatched keys that break it, the allow-list lines that are stale (the key
/// matches now, or is not listed), and the count of unmatched keys that are allowed. `profile`
/// `None` (an archive built with other flags, e.g. the bench's x86-64-v3 copy, whose inlining
/// differs): nothing is checked, every unmatched key is counted.
fn unmatched<'a>(entries: &'a [Entry], matched: &BTreeSet<String>, absent: &BTreeSet<(String, String)>, profile: Option<&str>) -> (Vec<&'a Entry>, Vec<String>, usize) {
    let (mut dead, mut stale, mut allowed) = (Vec::new(), Vec::new(), 0);
    let Some(p) = profile else {
        return (dead, stale, entries.iter().filter(|e| !matched.contains(&e.key)).count());
    };
    for e in entries.iter().filter(|e| !matched.contains(&e.key)) {
        let other_only = !e.profiles.is_empty() && !e.profiles.iter().any(|x| x == p);
        if other_only || absent.contains(&(e.key.clone(), p.to_string())) {
            allowed += 1;
        } else {
            dead.push(e);
        }
    }
    let listed: BTreeSet<&str> = entries.iter().map(|e| e.key.as_str()).collect();
    for (k, _) in absent.iter().filter(|(_, ap)| ap == p) {
        if matched.contains(k) || !listed.contains(k.as_str()) {
            stale.push(k.clone());
        }
    }
    (dead, stale, allowed)
}

/// The error for keys that break the dead-key contract (`None`: none do).
fn unmatched_error(dead: &[&Entry], stale: &[String], profile: &str) -> Option<String> {
    if dead.is_empty() && stale.is_empty() {
        return None;
    }
    let mut msg = String::new();
    if !dead.is_empty() {
        msg.push_str(&format!("hot-text.list: {} key(s) match no function section of the {profile}-profile libc.a", dead.len()));
        for e in dead {
            let traced = if e.profiles.is_empty() { "no trace".to_string() } else { format!("traced in {}", e.profiles.join(",")) };
            msg.push_str(&format!("\n  {} ({}, {traced})", e.key, e.tier));
        }
        msg.push_str(&format!(
            "\nrenamed, now generic or inlined: run tools/hottext/regen.sh . --build (in each profile); a key gone from every build: \
             tools/hottext/prune.py; a key absent from this profile by design: a line in crates/libc-so/{ABSENT_LIST} with its reason"
        ));
    }
    if !stale.is_empty() {
        msg.push_str(&format!("\n{ABSENT_LIST}: {} stale {profile} line(s) (the key matches a function section now, or is not in hot-text.list): remove them", stale.len()));
        for k in stale {
            msg.push_str(&format!("\n  {k}"));
        }
    }
    Some(msg.trim_start().to_string())
}

/// What [`repair_lists`] changed: the new texts of `hot-text.list` and [`ABSENT_LIST`], the keys
/// dropped from the list, the (key, profile) lines recorded in the allow-list and the stale
/// (key, profile) lines removed from it.
#[derive(Debug, Default, PartialEq)]
struct Repair {
    list: String,
    absent: String,
    dropped: Vec<String>,
    recorded: Vec<(String, String)>,
    removed: Vec<(String, String)>,
}

/// The cheap dead-key repair (HOTTEXT-DEAD-KEY-REPAIR) of `list` (`hot-text.list`) and `absent`
/// ([`ABSENT_LIST`]), given each profile's matched keys (`matched`: (profile, keys), both profiles):
/// a key no profile matches is dropped from the list (as tools/hottext/prune.py does); a key one
/// profile matches but another does not, where [`unmatched`] does not already allow it, gets an
/// allow-list line for that profile ("inlined in <profile> at <at>"); an allow-list line that
/// [`unmatched`] calls stale (its key matches now in its profile, or is no longer listed) is
/// removed. It never adds a key to the list and never reorders: every other line stays as it is.
fn repair_lists(list: &str, absent: &str, matched: &[(&str, &BTreeSet<String>)], at: &str) -> Result<Repair, String> {
    let entries = parse_list(list)?;
    let allowed = parse_absent(absent)?;
    let first_field = |l: &str| l.split('\t').next().unwrap_or("").trim().to_string();
    let is_data = |l: &str| !l.trim().is_empty() && !l.starts_with('#');
    let mut r = Repair::default();
    let gone: BTreeSet<&str> = entries.iter().filter(|e| !matched.iter().any(|(_, m)| m.contains(&e.key))).map(|e| e.key.as_str()).collect();
    for l in list.split_inclusive('\n') {
        let k = first_field(l);
        if is_data(l) && gone.contains(k.as_str()) {
            if !r.dropped.contains(&k) {
                r.dropped.push(k);
            }
        } else {
            r.list.push_str(l);
        }
    }
    let kept: BTreeSet<&str> = entries.iter().map(|e| e.key.as_str()).filter(|k| !gone.contains(k)).collect();
    for e in entries.iter().filter(|e| !gone.contains(e.key.as_str())) {
        for (p, m) in matched {
            let other_only = !e.profiles.is_empty() && !e.profiles.iter().any(|x| x == p);
            let pair = (e.key.clone(), p.to_string());
            if !m.contains(&e.key) && !other_only && !allowed.contains(&pair) && !r.recorded.contains(&pair) {
                r.recorded.push(pair);
            }
        }
    }
    for l in absent.split_inclusive('\n') {
        let mut f = l.trim_end_matches(['\n', '\r']).split('\t');
        let (k, p) = (f.next().unwrap_or(""), f.next().unwrap_or(""));
        let matches_now = matched.iter().any(|(mp, m)| *mp == p && m.contains(k));
        if is_data(l) && (!kept.contains(k) || matches_now) {
            r.removed.push((k.to_string(), p.to_string()));
        } else {
            r.absent.push_str(l);
        }
    }
    if !r.recorded.is_empty() && !r.absent.is_empty() && !r.absent.ends_with('\n') {
        r.absent.push('\n');
    }
    for (k, p) in &r.recorded {
        r.absent.push_str(&format!("{k}\t{p}\tinlined in {p} at {at} (cargo xtask hottext-repair)\n"));
    }
    Ok(r)
}

/// The dead-key contract of [`unmatched`] for every profile of `matched` on the texts of
/// `hot-text.list` (read from `file`) and [`ABSENT_LIST`], each profile's verdict of
/// [`dead_key_verdict`] under `mode`: the errors joined, or every profile's lines to print.
fn check_lists(list: &str, absent: &str, matched: &[(&str, &BTreeSet<String>)], file: &str, mode: DeadKeys) -> Result<Vec<String>, String> {
    let (entries, allowed) = (parse_list(list)?, parse_absent(absent)?);
    let (mut errs, mut lines) = (Vec::new(), Vec::new());
    for (p, m) in matched {
        let (dead, stale, _) = unmatched(&entries, m, &allowed, Some(p));
        match dead_key_verdict(&dead, &stale, p, file, mode) {
            Ok(l) => lines.extend(l),
            Err(e) => errs.push(e),
        }
    }
    if errs.is_empty() { Ok(lines) } else { Err(errs.join("\n")) }
}

/// `cargo xtask hottext-repair [--at <rev>]` (HOTTEXT-DEAD-KEY-REPAIR): the mechanical repair of
/// dead hot-text keys after `next` moved under a branch (merged in). Builds both profiles'
/// processed archives (the step of `cargo xtask so` that writes `target/product/<profile>/
/// hot-text.matched`, with the dead-key check reported, not enforced, as in [`REGEN_FLAG`]'s mode;
/// `target/liella` is not touched), applies [`repair_lists`] to `crates/libc-so/hot-text.list` and
/// [`ABSENT_LIST`], prints what it changed, and fails when the contract still does not hold for
/// either profile. `<rev>` names the revision in the recorded reasons (default: `git rev-parse
/// --short=12 origin/next`). No tracing and no new key: a real regen stays tools/hottext/regen.sh.
pub fn repair_cmd(root: &Path, args: &[String]) -> Result<(), String> {
    let at = match args {
        [] => {
            let o = Command::new("git").arg("-C").arg(root).args(["rev-parse", "--short=12", "origin/next"]).output().map_err(|e| format!("hottext-repair: git: {e}"))?;
            let sha = String::from_utf8_lossy(&o.stdout).trim().to_string();
            if !o.status.success() || sha.is_empty() {
                return Err("hottext-repair: no origin/next here: pass --at <next sha>".into());
            }
            sha
        }
        [flag, rev] if flag == "--at" && !rev.is_empty() && !rev.contains(char::is_whitespace) => rev.clone(),
        _ => return Err("usage: cargo xtask hottext-repair [--at <rev>]".into()),
    };
    let product = root.join("target/product");
    let profiles = [crate::so::Profile::Fast, crate::so::Profile::Release];
    let mut sets = Vec::new();
    for p in profiles {
        let matched_file = product.join(p.name()).join("hot-text.matched");
        let _ = fs::remove_file(&matched_file);
        REGEN.store(true, Ordering::Relaxed);
        let built = crate::so::build_archive(root, &product, &product.join(p.name()).join("hottext-repair-libc.a"), None, p);
        REGEN.store(false, Ordering::Relaxed);
        built?;
        let text = fs::read_to_string(&matched_file).map_err(|e| format!("hottext-repair: {}: {e}", matched_file.display()))?;
        sets.push(text.lines().map(str::trim).filter(|l| !l.is_empty() && !l.starts_with('#')).map(str::to_string).collect::<BTreeSet<String>>());
    }
    let matched: Vec<(&str, &BTreeSet<String>)> = profiles.iter().map(|p| p.name()).zip(sets.iter()).collect();
    let (list_path, absent_path) = (crate::hotlists::path(root, "hot-text.list")?, root.join(crate::hotlists::TRACKED).join(ABSENT_LIST));
    let read = |p: &Path| fs::read_to_string(p).map_err(|e| format!("hottext-repair: {}: {e}", p.display()));
    let (list, absent) = (read(&list_path)?, read(&absent_path)?);
    let r = repair_lists(&list, &absent, &matched, &at)?;
    for k in &r.dropped {
        println!("hottext-repair: dropped {k} (no profile matches it)");
    }
    for (k, p) in &r.recorded {
        println!("hottext-repair: {ABSENT_LIST}: recorded {k} for {p} (inlined in {p} at {at})");
    }
    for (k, p) in &r.removed {
        println!("hottext-repair: {ABSENT_LIST}: removed stale {p} line {k}");
    }
    if r.list != list {
        fs::write(&list_path, &r.list).map_err(|e| e.to_string())?;
    }
    if r.absent != absent {
        fs::write(&absent_path, &r.absent).map_err(|e| e.to_string())?;
    }
    if r.dropped.is_empty() && r.recorded.is_empty() && r.removed.is_empty() {
        println!("hottext-repair: nothing dead (no file changed)");
    } else {
        println!("hottext-repair: {} key(s) dropped, {} {ABSENT_LIST} line(s) recorded, {} stale line(s) removed", r.dropped.len(), r.recorded.len(), r.removed.len());
    }
    let lines = check_lists(&r.list, &r.absent, &matched, &list_path.display().to_string(), DeadKeys::from_env())
        .map_err(|e| format!("hottext-repair: the dead-key check still fails after the repair:\n{e}"))?;
    for l in lines {
        println!("hottext-repair: {l}");
    }
    Ok(())
}

/// A function section's name without any hot prefix: `.text.sorted.h<n>.<f>`, the older
/// `.text.hot.<f>`, rustc's `.text.unlikely.<f>` (a `#[cold]` function) and plain `.text.<f>` all
/// give `<f>`. `None` for other sections.
fn function_of(section: &str) -> Option<&str> {
    let f = section.strip_prefix(".text.")?;
    // LAYOUT-TEXT-PIN: `.text.startup.<f>` / `.text.exit.<f>` (GCC) and this tool's own
    // [`COLD_PREFIX`] carry the function name the same way.
    if let Some(name) = f.strip_prefix(COLD_PREFIX) {
        return Some(name.strip_suffix(COLD_SUFFIX).unwrap_or(name));
    }
    for p in ["unlikely.", "startup.", "exit."] {
        if let Some(name) = f.strip_prefix(p) {
            return Some(name);
        }
    }
    if let Some(rest) = f.strip_prefix("sorted.h") {
        let digits = rest.bytes().take_while(u8::is_ascii_digit).count();
        if digits > 0 {
            if let Some(name) = rest.get(digits..).and_then(|r| r.strip_prefix('.')) {
                return Some(name);
            }
        }
    }
    Some(f.strip_prefix("hot.").unwrap_or(f))
}

/// The section name `f` gets: `.text.sorted.h<position>.<f>` when its key is listed, else `.text.<f>`.
fn section_for(f: &str, keys: &BTreeMap<String, usize>) -> String {
    match keys.get(&key(f)) {
        Some(i) => format!(".text.sorted.h{i:05}.{f}"),
        None => format!(".text.{f}"),
    }
}

/// LAYOUT-TEXT-PIN (D-X.63): the prefix (after `.text.`) and suffix of an unlisted function whose
/// plain `.text.<f>` would itself match one of GNU ld's pre-group patterns (a function named `exit`
/// gets `.text.exit`; the suffix breaks `.text.*_unlikely`). [`function_of`] strips both, so a
/// later listing still finds the key.
const COLD_PREFIX: &str = "liella_cold.";
const COLD_SUFFIX: &str = ".liella_cold";

/// Whether GNU ld's default script (2.42) places input section `name` ahead of the hot group:
/// `*(.text.unlikely .text.*_unlikely .text.unlikely.*)`, `*(.text.exit .text.exit.*)`,
/// `*(.text.startup .text.startup.*)`, `*(.text.hot .text.hot.*)`.
fn before_group(name: &str) -> bool {
    let Some(f) = name.strip_prefix(".text.") else { return false };
    f.ends_with("_unlikely") || ["unlikely", "exit", "startup", "hot"].iter().any(|p| f == *p || f.strip_prefix(p).is_some_and(|r| r.starts_with('.')))
}

/// The name function section `name` (of function `f`) should have: [`section_for`], and for an
/// unlisted function a name GNU ld places after the hot group, with the cold rest of `.text`.
/// HOTTEXT-COLD-STARTUP: start-up runs `#[cold]` functions (`cpu::init`, the heap's first refill,
/// `resolve_fold_slow`), which rustc puts in `.text.unlikely.<f>`; listed, they join the hot group
/// in list order. LAYOUT-TEXT-PIN (D-X.63): unlisted, they used to stay in `.text.unlikely.*`
/// (with `.text.exit` of `exit` and any unlisted `.text.hot.*`), which ld places ahead of the
/// group, so every cold function added anywhere in the library moved every window boundary inside
/// the group. Now nothing of the library precedes the group (TEXT-PREFIX).
fn rename_for(_name: &str, f: &str, keys: &BTreeMap<String, usize>) -> String {
    let want = section_for(f, keys);
    if before_group(&want) { format!(".text.{COLD_PREFIX}{f}{COLD_SUFFIX}") } else { want }
}

/// LAYOUT-TEXT-PIN (D-X.63): the 0-fault clusters of the hot group, next to the list:
/// `<name> TAB <first key> TAB <last key>`, `#` comments. A cluster is every list position from
/// its first key's to its last key's; the hand-kept file names keys, so a regen that moves them
/// moves the cluster with them.
pub const CLUSTER_LIST: &str = "hot-text.clusters";
/// GNU ld 2.42 and the kernel's fault-around window on the reference hosts (64 KiB).
const WINDOW: u64 = 0x10000;

/// One cluster: name and the inclusive range of list positions.
#[derive(Debug, PartialEq)]
struct Cluster {
    name: String,
    first: usize,
    last: usize,
}

/// Parses [`CLUSTER_LIST`] against the list's `keys` (key to position).
fn parse_clusters(text: &str, keys: &BTreeMap<String, usize>) -> Result<Vec<Cluster>, String> {
    let mut out = Vec::new();
    for (n, l) in text.lines().enumerate() {
        let l = l.trim_end();
        if l.is_empty() || l.starts_with('#') || l.starts_with('@') {
            continue;
        }
        let f: Vec<&str> = l.split('\t').collect();
        let [name, a, b] = f[..] else { return Err(format!("{CLUSTER_LIST}:{}: want <name> TAB <first key> TAB <last key>", n + 1)) };
        let pos = |k: &str| keys.get(k).copied().ok_or_else(|| format!("{CLUSTER_LIST}:{}: cluster {name}: key {k} is not in the hot-text list", n + 1));
        let (first, last) = (pos(a)?, pos(b)?);
        if first > last {
            return Err(format!("{CLUSTER_LIST}:{}: cluster {name}: first key after last key ({first} > {last})", n + 1));
        }
        out.push(Cluster { name: name.to_string(), first, last });
    }
    Ok(out)
}

/// LAYOUT-TEXT-PIN-4 (D-X.63): `@place TAB end` in [`CLUSTER_LIST`] moves every cluster, in the
/// file's order, after the last list position: the start-up and plain text before it then has no
/// alignment gap inside it (STARTUP-TEXT-WINDOWS), and the clusters' gaps sit side by side.
/// `@place TAB in-place` (or no line) keeps each cluster at its list positions.
fn clusters_at_end(text: &str) -> Result<bool, String> {
    let mut end = false;
    for (n, l) in text.lines().enumerate() {
        let Some(d) = l.trim_end().strip_prefix('@') else { continue };
        end = match d.split('\t').collect::<Vec<_>>()[..] {
            ["place", "end"] => true,
            ["place", "in-place"] => false,
            _ => return Err(format!("{CLUSTER_LIST}:{}: want @place TAB end|in-place", n + 1)),
        };
    }
    Ok(end)
}

/// The name of grouped section `.text.sorted.h<position>.<f>` when it is moved to the end with
/// cluster `index` (file order): `.text.sorted.h9<index, 2 digits><position, 5 digits>.<f>`. It
/// sorts after every list position (5 digits, below 90000) and keeps the `h<digits>.` shape every
/// reader of grouped names expects.
fn cluster_section(index: usize, position: usize, f: &str) -> String {
    format!(".text.sorted.h9{index:02}{position:05}.{f}")
}

/// The list position in a grouped section name (`.text.sorted.h<position>.<f>`, or the moved
/// form of [`cluster_section`]).
fn position_of(section: &str) -> Option<usize> {
    let rest = section.strip_prefix(".text.sorted.h")?;
    let digits = rest.bytes().take_while(u8::is_ascii_digit).count();
    let d = rest.get(..digits)?;
    let d = if digits == 8 && d.starts_with('9') { &d[3..] } else { d };
    d.parse().ok()
}

/// The bytes the grouped sections `secs` (name, size, alignment) occupy when GNU ld lays them out
/// in name order (`SORT(.text.sorted.*)`) from an address aligned to all of them. An upper bound
/// for any one link: a link pulls in only some of the archive's members.
fn cluster_bytes(secs: &mut [(String, u64, u64)]) -> u64 {
    secs.sort_by(|a, b| a.0.cmp(&b.0));
    secs.iter().fold(0, |off, (_, size, align)| off.next_multiple_of((*align).max(1)) + size)
}

/// The alignment a cluster of `bytes` gets: the smallest power of two not below it (so the
/// cluster cannot straddle a [`WINDOW`] boundary wherever the link puts it), at least `min` (its
/// members' own alignment), at most [`WINDOW`] (a larger cluster then costs ceil(bytes / WINDOW)).
fn cluster_align(bytes: u64, min: u64) -> u64 {
    bytes.next_power_of_two().max(min).min(WINDOW)
}

/// The new alignment of each cluster head whose alignment differs, (member, name, alignment).
/// `grouped` is (member, name, size, alignment) as in the archive, which `so` copies fresh from
/// cargo's build on every run: every alignment there is the one its object asked for, and every
/// section that heads no cluster keeps it. Some ask for a page themselves: machine/fold.S's
/// classed memset pages (the start-up swap moves one page over the other, D-4.53).
fn head_alignments(grouped: &[(String, String, u64, u64)], heads: &BTreeMap<(String, String), u64>) -> Vec<(String, String, u64)> {
    grouped
        .iter()
        .filter_map(|(m, n, _, a)| heads.get(&(m.clone(), n.clone())).filter(|h| *h != a).map(|h| (m.clone(), n.clone(), *h)))
        .collect()
}

/// (name, size, alignment) of every section of the ELF64 little-endian object `obj`, read from
/// its section headers. Not `readelf -SW`: it cuts names at 256 bytes, so a long mangled name
/// would be renamed under a name no section has (LAYOUT-STARTUP-RODATA-3, #4354).
fn section_table(obj: &Path) -> Result<Vec<(String, u64, u64)>, String> {
    let b = fs::read(obj).map_err(|e| format!("{}: {e}", obj.display()))?;
    elf_sections(&b).ok_or_else(|| format!("{}: not a well-formed ELF64 little-endian object", obj.display()))
}

/// [`section_table`] of the bytes `b`; `None` when they are not a well-formed ELF64 LE file.
fn elf_sections(b: &[u8]) -> Option<Vec<(String, u64, u64)>> {
    Some(elf_headers(b)?.into_iter().map(|s| (s.name, s.size, s.align)).collect())
}

/// One section header of an ELF64 object, as [`elf_headers`] reads it.
pub(crate) struct Shdr {
    pub(crate) name: String,
    /// `sh_type` (`SHT_NOBITS` = 8 for zero-filled sections).
    pub(crate) kind: u32,
    pub(crate) size: u64,
    pub(crate) align: u64,
}
pub(crate) const SHT_NOBITS: u32 = 8;

/// The section headers of the ELF64 little-endian object `b`, in index order, with whole names;
/// `None` when `b` is not a well-formed ELF64 LE file.
pub(crate) fn elf_headers(b: &[u8]) -> Option<Vec<Shdr>> {
    let u16_at = |o: usize| Some(u16::from_le_bytes(b.get(o..o.checked_add(2)?)?.try_into().ok()?));
    let u32_at = |o: usize| Some(u32::from_le_bytes(b.get(o..o.checked_add(4)?)?.try_into().ok()?));
    let u64_at = |o: usize| Some(u64::from_le_bytes(b.get(o..o.checked_add(8)?)?.try_into().ok()?));
    if b.get(..6)? != b"\x7fELF\x02\x01" {
        return None;
    }
    let shoff = usize::try_from(u64_at(0x28)?).ok()?;
    let entsize = usize::from(u16_at(0x3a)?);
    if entsize < 64 {
        return None;
    }
    let hdr = |i: usize| i.checked_mul(entsize).and_then(|o| o.checked_add(shoff));
    // Extended numbering: a count of 0 / an index of SHN_XINDEX live in section header 0.
    let mut count = usize::from(u16_at(0x3c)?);
    if count == 0 {
        count = usize::try_from(u64_at(hdr(0)?.checked_add(32)?)?).ok()?;
    }
    let mut strndx = usize::from(u16_at(0x3e)?);
    if strndx == 0xffff {
        strndx = usize::try_from(u32_at(hdr(0)?.checked_add(40)?)?).ok()?;
    }
    let strtab = usize::try_from(u64_at(hdr(strndx)?.checked_add(24)?)?).ok()?;
    let mut out = Vec::with_capacity(count);
    for i in 0..count {
        let h = hdr(i)?;
        let name_at = strtab.checked_add(usize::try_from(u32_at(h)?).ok()?)?;
        let rest = b.get(name_at..)?;
        let name = rest.get(..rest.iter().position(|c| *c == 0)?)?;
        out.push(Shdr {
            name: String::from_utf8_lossy(name).into_owned(),
            kind: u32_at(h.checked_add(4)?)?,
            size: u64_at(h.checked_add(32)?)?,
            align: u64_at(h.checked_add(48)?)?,
        });
    }
    Some(out)
}

/// The members of the System V / GNU `ar` archive `data` in archive order: (name, bytes). Long
/// names (`/<offset>` into the `//` member) are resolved; the symbol tables (`/`, `/SYM64/`) and
/// the long-name table itself are left out.
pub(crate) fn ar_members(data: &[u8]) -> Result<Vec<(String, &[u8])>, String> {
    if data.get(..8) != Some(b"!<arch>\n".as_slice()) {
        return Err("not an ar archive".into());
    }
    let mut at = 8;
    let mut names: &[u8] = &[];
    let mut out: Vec<(String, &[u8])> = Vec::new();
    while at < data.len() {
        let h = data.get(at..at + 60).ok_or_else(|| format!("member header at {at} cut short"))?;
        let size: usize = std::str::from_utf8(&h[48..58]).ok().and_then(|s| s.trim().parse().ok()).ok_or_else(|| format!("member header at {at}: bad size"))?;
        let body = data.get(at + 60..(at + 60).checked_add(size).ok_or("member size overflows")?).ok_or_else(|| format!("member at {at} runs past the end"))?;
        let raw = String::from_utf8_lossy(&h[..16]);
        let raw = raw.trim_end();
        if raw == "//" {
            names = body;
        } else if raw != "/" && raw != "/SYM64/" {
            let name = match raw.strip_prefix('/') {
                Some(off) => {
                    let off: usize = off.parse().map_err(|_| format!("member name `{raw}`"))?;
                    let rest = names.get(off..).ok_or_else(|| format!("long name offset {off} past the name table"))?;
                    let end = rest.windows(2).position(|w| w == b"/\n").ok_or_else(|| format!("long name at {off} not terminated"))?;
                    String::from_utf8_lossy(&rest[..end]).into_owned()
                }
                None => raw.strip_suffix('/').unwrap_or(raw).to_string(),
            };
            out.push((name, body));
        }
        at += 60 + size + size % 2;
    }
    Ok(out)
}

/// The section headers of every ELF member of the archive at `path`: (member, headers), in
/// archive order. A member with the ELF magic that does not parse is an error.
pub(crate) fn archive_headers(path: &Path) -> Result<Vec<(String, Vec<Shdr>)>, String> {
    let data = fs::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let mut out = Vec::new();
    for (m, b) in ar_members(&data).map_err(|e| format!("{}: {e}", path.display()))? {
        if !b.starts_with(b"\x7fELF") {
            continue;
        }
        let h = elf_headers(b).ok_or_else(|| format!("{}({m}): not a well-formed ELF64 little-endian object", path.display()))?;
        out.push((m, h));
    }
    Ok(out)
}

/// Check that every `from -> to` rename of `renames` (by member) took effect in `members` (the
/// headers read back after the rename): `to` is there and `from` is gone (unless another rename
/// of the member produces it). `objcopy --rename-section` with a name no section has does
/// nothing and says nothing. Returns the number of renames checked.
pub(crate) fn check_renames(members: &[(String, Vec<Shdr>)], renames: &BTreeMap<String, Vec<(String, String)>>) -> Result<usize, String> {
    let mut bad = Vec::new();
    let mut n = 0;
    for (m, list) in renames {
        let Some((_, h)) = members.iter().find(|(name, _)| name == m) else {
            bad.push(format!("{m}: member missing after the rename"));
            continue;
        };
        let has = |s: &str| h.iter().any(|x| x.name == s);
        for (from, to) in list {
            n += 1;
            if !has(to) {
                bad.push(format!("{m}: {to} missing (renamed from {from})"));
            } else if from != to && has(from) && !list.iter().any(|(_, t)| t == from) {
                bad.push(format!("{m}: {from} still there (wanted {to})"));
            }
        }
    }
    if bad.is_empty() {
        Ok(n)
    } else {
        Err(format!("{} of {n} section renames did not take effect:\n  {}", bad.len(), bad.join("\n  ")))
    }
}

/// STARTUP-READ-CONSTANTS: the key suffix of `liella_boundary::startup_names::STARTUP_NAMES`, the
/// one static that holds the names start-up reads. Its section (`.rodata.<symbol>`) is renamed
/// [`STARTUP_SECTION`]: GNU ld's default script places `*(.rodata1)` right after `.rodata`, so
/// the static no longer sits between constants that move with unrelated code. The static's
/// alignment (at least its size) keeps it inside one 64 KiB fault-around window.
const STARTUP_KEY_SUFFIX: &str = "13startup_names13STARTUP_NAMES";
pub const STARTUP_SECTION: &str = ".rodata1";

/// Whether `section` is the start-up names' section, renamed or not.
fn is_startup_names(section: &str) -> bool {
    section.strip_prefix(".rodata.").is_some_and(|s| key(s).ends_with(STARTUP_KEY_SUFFIX))
}

/// Rename the function sections of `archive` whose keys are in `list` to
/// `.text.sorted.h<position>.<f>`, in place, and any hot section whose key is not listed (or whose
/// position changed) back to `.text.<f>` (or its new position): cargo may hand back an archive this
/// already ran on, with another list. `work` is a scratch directory. `profile`: the profile the
/// archive was built with (`fast`, `release`), `None` for other flags (see [`unmatched`]). A key traced in
/// `profile` that matches no function section is a warning, or fails under [`PROMOTE_ENV`]
/// ([`dead_key_verdict`]); a stale [`ABSENT_LIST`] line fails; prints the count of the allowed
/// unmatched keys. Returns (hot sections in the result, keys in the list). `inputs`: the directory of the
/// hand-written inputs ([`CLUSTER_LIST`], [`ABSENT_LIST`]); `list` may be a train-owned copy elsewhere (hotlists.rs).
pub fn group(ar: &str, archive: &Path, list: &Path, inputs: &Path, work: &Path, profile: Option<&str>) -> Result<(usize, usize), String> {
    let text = fs::read_to_string(list).map_err(|e| format!("{}: {e}", list.display()))?;
    let entries = parse_list(&text)?;
    let clusters_path = inputs.join(CLUSTER_LIST);
    let clusters_text = fs::read_to_string(&clusters_path).map_err(|e| format!("{}: {e}", clusters_path.display()));
    // LAYOUT-FIRST-WINDOW: link positions, the first-window keys right after the start-up tier.
    let keys = match first_window_positions(inputs, &entries, clusters_text.as_deref().ok()) {
        Ok(k) => k,
        Err(e) if REGEN.load(Ordering::Relaxed) => {
            println!("so: {REGEN_FLAG}: {FIRST_WINDOW_LIST} NOT applied for this regen build: {e}");
            positions(&entries)
        }
        Err(e) => return Err(e),
    };
    let mut matched = BTreeSet::new();
    let _ = fs::remove_dir_all(work);
    fs::create_dir_all(work).map_err(|e| e.to_string())?;
    let archive = fs::canonicalize(archive).map_err(|e| e.to_string())?;
    let listed = Command::new(ar).arg("t").arg(&archive).output().map_err(|e| format!("ar t: {e}"))?;
    let members: Vec<String> = String::from_utf8_lossy(&listed.stdout).lines().map(str::to_string).collect();
    if members.iter().collect::<BTreeSet<_>>().len() != members.len() {
        return Err(format!("{}: duplicate member names; cannot extract them safely", archive.display()));
    }
    crate::so::run(Command::new(ar).current_dir(work).arg("x").arg(&archive))?;
    let objcopy = std::env::var("OBJCOPY").unwrap_or_else(|_| "objcopy".into());
    let clusters = match &clusters_text {
        Ok(t) => parse_clusters(t, &keys).and_then(|c| Ok((c, clusters_at_end(t)?))),
        Err(e) => Err(e.clone()),
    };
    // A regen build must not be blocked by a cluster key the old list lacks (D-X.56).
    let (clusters, at_end) = match clusters {
        Ok(c) => c,
        Err(e) if REGEN.load(Ordering::Relaxed) => {
            println!("so: {REGEN_FLAG}: hot-text clusters NOT aligned for this regen build: {e}");
            (Vec::new(), false)
        }
        Err(e) => return Err(e),
    };
    let mut hot = 0;
    let mut startup = 0;
    let mut changed = Vec::new();
    let mut renames: BTreeMap<String, Vec<(String, String)>> = BTreeMap::new();
    // Every grouped section: (member, name after renaming, size, alignment).
    let mut grouped: Vec<(String, String, u64, u64)> = Vec::new();
    for m in &members {
        let obj = work.join(m);
        let mut args = String::new();
        for (name, size, align) in section_table(&obj)? {
            let name = &name;
            if name == STARTUP_SECTION {
                startup += 1;
                continue;
            }
            if is_startup_names(name) {
                startup += 1;
                args.push_str(&format!("--rename-section {name}={STARTUP_SECTION}\n"));
                renames.entry(m.clone()).or_default().push((name.clone(), STARTUP_SECTION.to_string()));
                continue;
            }
            let Some(f) = function_of(name) else { continue };
            matched.insert(key(f));
            let mut want = rename_for(name, f, &keys);
            if at_end {
                if let Some((i, p)) = position_of(&want).and_then(|p| clusters.iter().position(|c| (c.first..=c.last).contains(&p)).map(|i| (i, p))) {
                    want = cluster_section(i, p, f);
                }
            }
            if want.starts_with(".text.sorted.") {
                hot += 1;
                grouped.push((m.clone(), want.clone(), size, align));
            }
            if want != *name {
                args.push_str(&format!("--rename-section {name}={want}\n"));
                renames.entry(m.clone()).or_default().push((name.clone(), want.clone()));
            }
        }
        if !args.is_empty() {
            let rsp = work.join(format!("{m}.rsp"));
            fs::write(&rsp, args).map_err(|e| e.to_string())?;
            crate::so::run(Command::new(&objcopy).arg(format!("@{}", rsp.display())).arg(&obj))?;
            changed.push(m.clone());
        }
    }
    // LAYOUT-TEXT-PIN (D-X.63): the head of each 0-fault cluster gets the smallest power-of-two
    // alignment not below the cluster's size, so the cluster sits inside one fault-around window
    // wherever the rest of the program moves the group (CLUSTER-WINDOW). Done after the renames,
    // on the final names; every other section keeps its own ([`head_alignments`]).
    let mut realign: BTreeMap<String, Vec<(String, u64)>> = BTreeMap::new();
    let mut heads = BTreeMap::new();
    for c in &clusters {
        let mut secs: Vec<(String, u64, u64)> = grouped
            .iter()
            .filter(|(_, n, _, _)| position_of(n).is_some_and(|p| (c.first..=c.last).contains(&p)))
            .map(|(_, n, s, a)| (n.clone(), *s, *a))
            .collect();
        let min = secs.iter().map(|s| s.2).max().unwrap_or(1);
        let bytes = cluster_bytes(&mut secs);
        let Some(head) = secs.iter().find(|s| s.1 > 0).map(|s| s.0.clone()) else {
            return Err(format!("{CLUSTER_LIST}: cluster {} (positions {}..={}) has no section in {}", c.name, c.first, c.last, archive.display()));
        };
        let align = cluster_align(bytes, min);
        println!("so: hot-text cluster {}: positions {}..={}, {} sections, {bytes} bytes, aligned {align}", c.name, c.first, c.last, secs.len());
        for (m, n, _, _) in grouped.iter().filter(|g| g.1 == head) {
            heads.insert((m.clone(), n.clone()), align);
        }
    }
    for (m, n, a) in head_alignments(&grouped, &heads) {
        realign.entry(m).or_default().push((n, a));
    }
    for (m, list) in &realign {
        let mut cmd = Command::new(&objcopy);
        for (n, a) in list {
            cmd.arg(format!("--set-section-alignment={n}={a}"));
        }
        crate::so::run(cmd.arg(work.join(m)))?;
        if !changed.contains(m) {
            changed.push(m.clone());
        }
    }
    if !changed.is_empty() {
        crate::so::run(Command::new(ar).current_dir(work).arg("r").arg(&archive).args(&changed))?;
    }    let checked = check_renames(&archive_headers(&archive)?, &renames).map_err(|e| format!("{}: hot-text grouping: {e}", archive.display()))?;
    println!("so: hot-text grouping: {checked} section renames, all in effect");
    let _ = fs::remove_dir_all(work);
    if startup != 1 {
        return Err(format!("{}: {startup} start-up names sections (STARTUP_NAMES), want 1", archive.display()));
    }
    let absent_path = inputs.join(ABSENT_LIST);
    let absent = match fs::read_to_string(&absent_path) {
        Ok(t) => parse_absent(&t)?,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => BTreeSet::new(),
        Err(e) => return Err(format!("{}: {e}", absent_path.display())),
    };
    // The archive's function keys, for tools/hottext/prune.py (a key no build matches is dropped).
    let mut keys_out: String = matched.iter().map(|k| format!("{k}\n")).collect();
    keys_out.insert_str(0, "# function keys of this archive (cargo xtask so; tools/hottext/prune.py reads it)\n");
    fs::write(archive.with_file_name("hot-text.matched"), keys_out).map_err(|e| e.to_string())?;
    let (dead, stale, allowed) = unmatched(&entries, &matched, &absent, profile);
    for l in dead_key_verdict(&dead, &stale, profile.unwrap_or(""), &list.display().to_string(), DeadKeys::from_env())? {
        println!("so: {l}");
    }
    println!("so: {allowed} hot-text keys match no function section (traced in the other profile only, or in {ABSENT_LIST})");
    Ok((hot, keys.len()))
}

/// LAYOUT-DEADKEY-WARN (owner ruling #5193, amending D-X.53 (2)): the environment variable that makes a
/// dead hot-text key fail. Only the next->main promotion run sets it (`LIELLA_PROMOTE=1`); everywhere
/// else (`so`, the gate, the plants baseline, the train, `hottext-recheck`, `hottext-repair`) a dead key
/// is a warning. Read once, by [`DeadKeys::from_env`]; the tests pass the mode explicitly.
pub const PROMOTE_ENV: &str = "LIELLA_PROMOTE";

/// How the dead-key check of [`group`] and [`check_lists`] ends (see [`dead_key_verdict`]).
#[derive(Clone, Copy, Debug, PartialEq)]
enum DeadKeys {
    /// [`REGEN_FLAG`]'s build: dead keys and stale allow-list lines are printed, nothing fails.
    Regen,
    /// The default: each dead key is a warning line; a stale [`ABSENT_LIST`] line still fails.
    Warn,
    /// [`PROMOTE_ENV`] is `1`: a dead key fails, as does a stale allow-list line.
    Promote,
}

impl DeadKeys {
    /// The mode for the regen flag and the value of [`PROMOTE_ENV`] (`None`: unset). Regen wins: a
    /// regen build is an intermediate step whose rebuild is checked.
    fn of(regen: bool, promote: Option<&std::ffi::OsStr>) -> DeadKeys {
        if regen {
            DeadKeys::Regen
        } else if promote.is_some_and(|v| v == "1") {
            DeadKeys::Promote
        } else {
            DeadKeys::Warn
        }
    }

    /// The mode of this process: the regen flag and the caller's [`PROMOTE_ENV`].
    fn from_env() -> DeadKeys {
        DeadKeys::of(REGEN.load(Ordering::Relaxed), std::env::var_os(PROMOTE_ENV).as_deref())
    }
}

/// The dead-key check's outcome for `profile` (`file`: the list read): `Err` fails the caller, `Ok`
/// holds the lines to print. A stale [`ABSENT_LIST`] line fails except in the regen mode; a dead key
/// fails only under [`DeadKeys::Promote`] and is otherwise one warning line per key (key, file,
/// profile) and a count line.
fn dead_key_verdict(dead: &[&Entry], stale: &[String], profile: &str, file: &str, mode: DeadKeys) -> Result<Vec<String>, String> {
    match mode {
        DeadKeys::Regen => Ok(unmatched_error(dead, stale, profile).map(|e| format!("{REGEN_FLAG}: dead-key check NOT enforced for this regen build (regen.sh rewrites the list, then rebuilds with it):\n{e}")).into_iter().collect()),
        DeadKeys::Promote => unmatched_error(dead, stale, profile).map_or(Ok(Vec::new()), |e| Err(format!("{e}\n({PROMOTE_ENV}=1: dead keys fail in the promotion run)"))),
        DeadKeys::Warn => {
            if let Some(e) = unmatched_error(&[], stale, profile) {
                return Err(e);
            }
            let mut out: Vec<String> = dead
                .iter()
                .map(|e| format!("warning: dead hot-text key {} ({}) in {file}: matches no function section of the {profile}-profile libc.a", e.key, e.tier))
                .collect();
            if !dead.is_empty() {
                out.push(format!(
                    "warning: {} dead hot-text key(s) in the {profile} profile (not enforced; {PROMOTE_ENV}=1, the promotion run, fails on them; repair: cargo xtask hottext-repair or tools/hottext/regen.sh)",
                    dead.len()
                ));
            }
            Ok(out)
        }
    }
}

/// Whether tracked file `path` may name [`REGEN_FLAG`]: its definition, its one caller
/// (`tools/hottext/regen.sh`) and prose (`.md`, and the records under `records/`, which only xtask
/// reads). A gate, CI script or other tool that passed it
/// would build with the dead-key check off.
fn may_name_regen_flag(path: &str) -> bool {
    path == "xtask/src/hottext.rs" || path == "tools/hottext/regen.sh" || path.ends_with(".md")
        || (path.starts_with("records/") && path.ends_with(".toml"))
}

/// Where the function a v0 key names is defined (LAYOUT-HOTKEY-INLINE-STABLE): crate, module
/// path, the self type's name for a method of an inherent or trait impl, the function's name.
#[derive(Debug, PartialEq)]
struct Site {
    krate: String,
    mods: Vec<String>,
    owner: Option<String>,
    f: String,
}

/// The [`Site`] of a key naming a function, generic (`I ... E`) or not: `Nv` over a module path,
/// an inherent impl (`M`) or a trait impl (`X`). `None` for a closure, a trait's provided method, a
/// C name and anything that does not parse.
fn fn_site(key: &str) -> Option<Site> {
    let mut d = V0 { b: key.strip_prefix("_R")?.as_bytes(), depth: 0 };
    let i = usize::from(d.at(0)? == b'I');
    if d.at(i)? != b'N' || d.at(i + 1)? != b'v' {
        return None;
    }
    let (krate, mods, owner, j) = d.owner(i + 2)?;
    let f = d.name(j)?.0;
    Some(Site { krate, mods, owner, f })
}

/// Whether every definition of `fn f` in `text` carries `#[inline(never)]` among the attributes and
/// comments directly above it: the module-level definitions for a free function (`owner` `None`),
/// the indented ones inside an `impl` block whose header line names `owner` for a method; `None`
/// when `text` has no such definition.
fn inline_never(text: &str, f: &str, owner: Option<&str>) -> Option<bool> {
    let lines: Vec<&str> = text.lines().collect();
    let (mut found, mut header) = (None, None);
    for (i, l) in lines.iter().enumerate() {
        let t = l.trim_start();
        if t.len() == l.len() && !t.is_empty() && !t.starts_with("#[") && !t.starts_with("//") {
            header = (t.starts_with("impl") || t.starts_with("unsafe impl")).then_some(t);
        }
        let in_place = match owner {
            None => t.len() == l.len(),
            Some(o) => t.len() < l.len() && header.is_some_and(|h| h.split(|c: char| !(c.is_alphanumeric() || c == '_')).any(|w| w == o)),
        };
        let mut rest = t;
        for q in ["pub(crate) ", "pub(super) ", "pub ", "const ", "unsafe ", "extern \"C\" "] {
            rest = rest.strip_prefix(q).unwrap_or(rest);
        }
        let Some(after) = rest.strip_prefix("fn ").and_then(|r| r.strip_prefix(f)) else { continue };
        if !in_place || (!after.starts_with('(') && !after.starts_with('<')) {
            continue;
        }
        let marked = lines[..i]
            .iter()
            .map(|a| a.trim())
            .rev()
            .take_while(|a| a.starts_with("#[") || a.starts_with("//"))
            .any(|a| a == "#[inline(never)]");
        found = Some(found.unwrap_or(true) && marked);
    }
    found
}

/// The source of module `mods` of workspace crate `krate` (its library name): `(path, text)`.
fn module_source(root: &Path, krate: &str, mods: &[String]) -> Option<(String, String)> {
    let package = krate.replace('_', "-");
    let dir = fs::read_dir(root.join("crates")).ok()?.filter_map(Result::ok).map(|e| e.path()).find(|d| {
        fs::read_to_string(d.join("Cargo.toml")).is_ok_and(|t| t.lines().any(|l| l.trim() == format!("name = \"{krate}\"") || l.trim() == format!("name = \"{package}\"")))
    })?;
    let base = dir.join("src").join(mods.join("/"));
    let candidates = if mods.is_empty() { vec![dir.join("src/lib.rs")] } else { vec![base.with_extension("rs"), base.join("mod.rs")] };
    candidates.into_iter().find_map(|p| fs::read_to_string(&p).ok().map(|t| (p.strip_prefix(root).unwrap_or(&p).display().to_string(), t)))
}

/// The tiers whose keys fail `cargo xtask so` when dead (D-X.47), so whose Rust functions must keep
/// their symbol in both profiles whatever unrelated code does to LLVM's inlining budget: two libm
/// merges inlined `spawn::wait4` away (2026-11-07), and on 2026-11-12 two libm changes inlined
/// `Vdso::lookup_many::<5>` (#4986) and another start-up function (#4991) in the fast archive.
/// Since D-X.53 a dead key of ANY tier fails `so`, and a dummy libm growth (LAYOUT-HOTKEY-INLINE-STABLE-2)
/// killed `locale::builtin` (locale), `nscache::real_secs` (tool) and `iconv::load` (extra): every
/// tier is checked (ruling #5024). Since ruling #5193 (LAYOUT-DEADKEY-WARN) a dead key fails only
/// the promotion run ([`PROMOTE_ENV`]) and warns elsewhere; the pin check here is unchanged.
const INLINE_NEVER_TIERS: [&str; 7] = TIERS;

/// The keys of hot-text.list that may name a function without a fixed boundary, one line each:
/// `<key>\t<tier>\t<reason>` (LAYOUT-HOTKEY-INLINE-STABLE). A key belongs here only when a call
/// boundary is not free (a hot path, or a measured cost) or no attribute of ours can pin it (a
/// closure, a function of `core` or `alloc`, a generic shared with hot instantiations). The tier
/// column is the key's tier when the line was written, a note for readers only: hot-text.list is
/// generated and train-owned, so a regen may move a key to another tier, and nothing reads the
/// tier here (every tier is checked alike, [`INLINE_NEVER_TIERS`], and no accepted reason depends
/// on the tier), so it is not compared (HOTTEXT-UNPINNED-TIER).
pub const UNPINNED_LIST: &str = "crates/libc-so/hot-text.unpinned";

/// The lines of [`UNPINNED_LIST`]: key -> (tier, reason). `#` comments and blank lines skipped.
fn parse_unpinned(text: &str) -> Result<BTreeMap<String, (String, String)>, String> {
    let mut out = BTreeMap::new();
    for (n, l) in text.lines().enumerate() {
        if l.trim().is_empty() || l.starts_with('#') {
            continue;
        }
        match l.split('\t').collect::<Vec<_>>()[..] {
            [k, tier, why] if k.starts_with("_R") && TIERS.contains(&tier) && !why.trim().is_empty() => {
                if out.insert(k.to_string(), (tier.to_string(), why.to_string())).is_some() {
                    return Err(format!("{UNPINNED_LIST} line {}: {k} listed twice", n + 1));
                }
            }
            _ => return Err(format!("{UNPINNED_LIST} line {}: {l:?}: want <v0 key>\\t<tier>\\t<reason>", n + 1)),
        }
    }
    Ok(out)
}

/// Why `key` (a key of an [`INLINE_NEVER_TIERS`] tier) has no fixed boundary, `None` when it has one:
/// a C name (an exported or assembly symbol always exists), or a workspace function whose every
/// definition is `#[inline(never)]`.
fn unpinned_reason(root: &Path, key: &str) -> Option<String> {
    if !key.starts_with("_R") {
        return None;
    }
    let Some(s) = fn_site(key) else { return Some("a closure or other symbol no attribute of ours can pin".to_string()) };
    if !s.krate.starts_with("liella") {
        return Some(format!("a function of crate {} (no attribute of ours can pin it)", s.krate));
    }
    let what = format!("fn {}{}", s.owner.as_ref().map_or(String::new(), |o| format!("{o}::")), s.f);
    match module_source(root, &s.krate, &s.mods) {
        None => Some(format!("module source of {}::{} not found", s.krate, s.mods.join("::"))),
        Some((path, text)) => match inline_never(&text, &s.f, s.owner.as_deref()) {
            Some(true) => None,
            Some(false) => Some(format!("{path}: {what} is not #[inline(never)]")),
            None => Some(format!("{path}: no definition of {what} found")),
        },
    }
}

/// The fixed-boundary check of [`static_check`] on the parsed list and unpinned lines: errors.
fn check_pinned(root: &Path, entries: &[Entry], unpinned: &BTreeMap<String, (String, String)>) -> Vec<String> {
    let mut errs = Vec::new();
    let checked = |k: &str| entries.iter().any(|e| e.key == k && INLINE_NEVER_TIERS.contains(&e.tier));
    for e in entries.iter().filter(|e| INLINE_NEVER_TIERS.contains(&e.tier)) {
        match (unpinned_reason(root, &e.key), unpinned.get(&e.key)) {
            (Some(why), None) => errs.push(format!(
                "hot-text.list: {} ({} key): {why}: unrelated code can make LLVM inline it and kill the key; mark it #[inline(never)] where a call boundary is free, or #[inline(always)] into a keyed caller and drop the key, or list it in {UNPINNED_LIST} with the reason",
                e.key, e.tier
            )),
            (None, Some(_)) if e.key.starts_with("_R") => errs.push(format!("{UNPINNED_LIST}: {} has a fixed boundary now: remove its line", e.key)),
            _ => {}
        }
    }
    for k in unpinned.keys().filter(|k| !checked(k)) {
        errs.push(format!("{UNPINNED_LIST}: {k} is no key of hot-text.list: remove its line"));
    }
    errs
}

/// `cargo xtask static` (HOTTEXT-REGEN-UNBLOCK, LAYOUT-HOTKEY-INLINE-STABLE): (1) no tracked file but
/// [`may_name_regen_flag`]'s names [`REGEN_FLAG`], so no gate can build with the dead-key check off;
/// (2) every Rust key of an [`INLINE_NEVER_TIERS`] tier names a workspace function that is
/// `#[inline(never)]` in the source (free, generic, inherent or trait method alike), so it keeps its
/// symbol (and its key) in both profiles, or is listed in [`UNPINNED_LIST`] with the reason; a line
/// there that no longer applies is an error too.
pub fn static_check(root: &Path) -> Result<(), String> {
    let mut errs = Vec::new();
    for p in crate::labnames::tracked_with(root, true)? {
        if may_name_regen_flag(&p) {
            continue;
        }
        if fs::read(root.join(&p)).is_ok_and(|b| String::from_utf8_lossy(&b).contains(REGEN_FLAG)) {
            errs.push(format!("{p}: names {REGEN_FLAG}; only tools/hottext/regen.sh may build with the dead-key check off"));
        }
    }
    let list = crate::hotlists::path(root, "hot-text.list")?;
    let entries = parse_list(&fs::read_to_string(&list).map_err(|e| format!("{}: {e}", list.display()))?)?;
    let unpinned = parse_unpinned(&fs::read_to_string(root.join(UNPINNED_LIST)).map_err(|e| format!("{UNPINNED_LIST}: {e}"))?)?;
    errs.extend(check_pinned(root, &entries, &unpinned));
    // LAYOUT-FIRST-WINDOW: a stale or misplaced first-window line fails here, before any build.
    let inputs = root.join(crate::hotlists::TRACKED);
    let clusters_text = fs::read_to_string(inputs.join(CLUSTER_LIST)).ok();
    if let Err(e) = first_window_positions(&inputs, &entries, clusters_text.as_deref()) {
        errs.push(e);
    }
    if errs.is_empty() { Ok(()) } else { Err(errs.join("\n")) }
}

